    long[] factorial, invFactorial;

    long nCr(int n, int r) {
        return factorial[n] * invFactorial[r] % mod * invFactorial[n - r] % mod;
    }

    void execute() {
        mod = 998244353L;
        int n = readInt();
        long k = readLong();
        if (k >= n) {
            writer.println(0);
        } else {
            factorial = new long[n + 1];
            invFactorial = new long[n + 1];
            factorial[0] = 1;
            invFactorial[0] = 1;
            for (int i = 1; i <= n; i++) {
                factorial[i] = (factorial[i - 1] * i) % mod;
            }
            invFactorial[n] = modPow(factorial[n], mod - 2);
            for (int i = n - 1; i >= 1; i--) {
